"""
Tutor plugin: ost2_unstarted_enrollment_guard   (OST2)

Limits "enrollment hoarding": a learner who is actively enrolled in THRESHOLD (5) or more
courses that are all still at 0% completion may not enroll in another course until they
unenroll from some of them.

  * GET  /too-many-unstarted-classes/            public explainer page (Li'l Stranger image)
  * GET  /too-many-unstarted-classes/image.webp
  * GET  /courses                                ("Discover New Courses") -> 302 to the page
  * POST /change_enrollment (enroll)             course-about "Enroll in" button -> 200 whose
                                                 body is the page URL (the about-page JS does
                                                 location.href = responseText)
  * POST /api/enrollment/v1/enrollment           Learning-MFE "Enroll now" link -> 403 JSON with
                                                 "ost2_redirect"; the MFE (tutor-indigo build
                                                 patch on enrollment-alert/data/api.js) follows it

"0% completion" = the learner has no BlockCompletion row with completion > 0 in that course
(what the Progress tab's completion summary counts). Global staff/superusers are exempt, as are
requests where the learner is already enrolled in the target course. Anonymous requests pass through.

LMS-only, no image rebuild: `tutor config save` + `tutor local restart lms`.
"""
from tutor import hooks

__version__ = "1.0.0"

_IMG_B64 = ""

_CODE = r"""
# ============================================================================
# OST2: unstarted-enrollment guard. Injected by the ost2_unstarted_enrollment_guard tutor plugin.
# ============================================================================
import base64 as _ost2_ue_b64
import json as _ost2_ue_json
import logging as _ost2_ue_logging

_ost2_ue_log = _ost2_ue_logging.getLogger("ost2.unstarted_guard")

OST2_UNSTARTED_THRESHOLD = 5
OST2_UNSTARTED_PATH = "/too-many-unstarted-classes"

_OST2_UE_IMAGE = _ost2_ue_b64.b64decode("@@IMG@@")

_OST2_UE_CSS = (
    ":root{--bg:#fff;--fg:#1f2937}"
    "@media (prefers-color-scheme: dark){:root{--bg:#111827;--fg:#e5e7eb}}"
    "body{margin:0;background:var(--bg);color:var(--fg);font:18px/1.6 Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif}"
    "main{max-width:760px;margin:0 auto;padding:32px 16px;text-align:center}"
    "h1{font-size:2.5rem;line-height:1.2;margin:0 0 1rem}"
    "img{max-width:100%;height:auto;max-height:70vh}"
    "p{margin:1rem 0 0}"
    "a{color:inherit}"
)


def _ost2_ue_page_view(request):
    from django.http import HttpResponse
    html = (
        '<!doctype html><html lang="en"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1">'
        '<meta name="color-scheme" content="light dark">'
        '<title>Unenroll from some existing classes!</title><style>' + _OST2_UE_CSS + '</style></head>'
        '<body><main>'
        '<h1>Unenroll from some existing classes!</h1>'
        '<img src="/too-many-unstarted-classes/image.webp" alt="Li&#39;l Stranger holding up a finger">'
        '<p>I currently see that you have at least 5 classes that you&#39;ve enrolled for, but are at 0% completion! '
        'We can&#39;t have you just &#39;starting&#39; classes willy-nilly and never completing them, or else it looks '
        'like OST2 students never finish their classes! So you&#39;ll need to unenroll from some existing classes that '
        'you don&#39;t plan on taking before you can enroll in a new class. '
        '(As a reminder, all classes&#39; outlines and even material is public, so there&#39;s no need to enroll '
        'just to see what kind of material is in a class.)</p>'
        '<p><a href="/dashboard">Go to My Enrolled Courses</a></p>'
        '</main></body></html>'
    )
    resp = HttpResponse(html)
    resp["Cache-Control"] = "no-store"
    return resp


def _ost2_ue_image_view(request):
    from django.http import HttpResponse
    resp = HttpResponse(_OST2_UE_IMAGE, content_type="image/webp")
    resp["Cache-Control"] = "public, max-age=86400"
    return resp


def ost2_unstarted_count(user):
    # Number of the user's active enrollments (in courses that still exist) with zero completion.
    from common.djangoapps.student.models import CourseEnrollment
    from openedx.core.djangoapps.content.course_overviews.models import CourseOverview
    from completion.models import BlockCompletion
    enrolled = list(
        CourseEnrollment.objects.filter(user=user, is_active=True).values_list("course_id", flat=True)
    )
    if not enrolled:
        return 0
    existing = set(CourseOverview.objects.filter(id__in=enrolled).values_list("id", flat=True))
    enrolled = [c for c in enrolled if c in existing]
    started = set(
        BlockCompletion.objects.filter(user=user, context_key__in=enrolled, completion__gt=0)
        .values_list("context_key", flat=True).distinct()
    )
    return len([c for c in enrolled if c not in started])


def ost2_enrollment_blocked(user, target_course_id=None):
    if user is None or not user.is_authenticated or user.is_staff or user.is_superuser:
        return False
    if target_course_id:
        from common.djangoapps.student.models import CourseEnrollment
        try:
            from opaque_keys.edx.keys import CourseKey
            key = CourseKey.from_string(target_course_id)
            if CourseEnrollment.is_enrolled(user, key):
                return False
        except Exception:
            pass
    return ost2_unstarted_count(user) >= OST2_UNSTARTED_THRESHOLD


class Ost2UnstartedEnrollmentGuard:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        try:
            early = self._check(request)
        except Exception:
            _ost2_ue_log.exception("ost2 unstarted guard: check failed (allowing request)")
            early = None
        return early if early is not None else self.get_response(request)

    def _check(self, request):
        from django.conf import settings
        from django.http import HttpResponse, HttpResponseRedirect, JsonResponse
        path = request.path
        user = getattr(request, "user", None)
        if user is None or not user.is_authenticated:
            return None
        target = settings.LMS_ROOT_URL + OST2_UNSTARTED_PATH + "/"
        if request.method == "GET" and path.rstrip("/") == "/courses":
            if ost2_enrollment_blocked(user):
                _ost2_ue_log.info("blocked /courses for user %s", user.id)
                return HttpResponseRedirect(target)
        elif request.method == "POST" and path.rstrip("/") == "/change_enrollment":
            if request.POST.get("enrollment_action") == "enroll" and ost2_enrollment_blocked(user, request.POST.get("course_id")):
                _ost2_ue_log.info("blocked change_enrollment for user %s", user.id)
                return HttpResponse(target, status=200)
        elif request.method == "POST" and path.rstrip("/") == "/api/enrollment/v1/enrollment":
            body = _ost2_ue_json.loads(request.body or b"null") or dict()
            other = body.get("user")
            if other and other != user.username:
                return None
            course_id = (body.get("course_details") or dict()).get("course_id")
            if ost2_enrollment_blocked(user, course_id):
                _ost2_ue_log.info("blocked enrollment API for user %s", user.id)
                return JsonResponse(
                    dict(
                        message="Too many unstarted classes: unenroll from some existing classes first.",
                        ost2_redirect=target,
                    ),
                    status=403,
                )
        return None


def _ost2_ue_install():
    import importlib
    from django.urls import re_path
    from django.conf import settings
    urls = importlib.import_module(settings.ROOT_URLCONF)
    if getattr(urls, "_ost2_ue_installed", False):
        return
    urls.urlpatterns.insert(0, re_path(r"^too-many-unstarted-classes/image\.webp$", _ost2_ue_image_view, name="ost2_unstarted_image"))
    urls.urlpatterns.insert(0, re_path(r"^too-many-unstarted-classes/?$", _ost2_ue_page_view, name="ost2_unstarted_page"))
    urls._ost2_ue_installed = True
    _ost2_ue_log.info("ost2 unstarted-classes page installed")


from django.core.signals import request_started as _ost2_ue_req
from django.dispatch import receiver as _ost2_ue_receiver


@_ost2_ue_receiver(_ost2_ue_req, dispatch_uid="ost2_unstarted_guard_install")
def _ost2_ue_boot(sender, **kwargs):
    try:
        _ost2_ue_install()
    except Exception:
        _ost2_ue_log.exception("ost2 unstarted guard: page install failed")


MIDDLEWARE = list(MIDDLEWARE) + [__name__ + ".Ost2UnstartedEnrollmentGuard"]
""".replace("@@IMG@@", _IMG_B64)

hooks.Filters.ENV_PATCHES.add_item(("openedx-lms-production-settings", _CODE))
